{
  "passageId": "corporate-law",
  "items": [
    {
      "id": "R1",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "법인이 독립적인 권리·의무의 주체라는 사실에서 자산 소유권이 법인에 귀속된다는 판단을 도출한다."
    },
    {
      "id": "R2",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "법인에게 행위 능력이 없다는 한계를 권한을 부여받은 사람이 실제 운용을 맡는 방식으로 보완한다."
    },
    {
      "id": "R3",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "권한을 받은 사람도 자산을 임의로 운용할 수는 없으며 절차와 목적을 위반하면 처벌받는다는 한계를 제시한다."
    },
    {
      "id": "R4",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "자산 운용에 대한 법적 통제가 공동체의 질서 유지를 위해 마련된 수단임을 설명한다."
    },
    {
      "id": "R5",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "법인의 일반적인 성격과 법적 통제에 관한 논의에서 법인 종류별 통제 차이에 관한 논의로 넘어간다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "법인 종류에 따라 통제 내용이 다르다는 일반적 설명을 장학 재단의 구체적인 사례로 보여 준다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "장학 재단이 비영리 법인이라는 사실을 근거로 경제적 이익을 추구하지 않는다고 판단한다."
    },
    {
      "id": "R8",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "장학 재단이 재단 법인이라는 사실에서 법인격이 자산 자체에 부여된다는 판단을 도출한다."
    },
    {
      "id": "R9",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "법인의 행위 능력 부재라는 한계를 보완하기 위해 이를 대신 행사하는 이사회를 설치한다."
    },
    {
      "id": "R10",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "이사회가 법인의 행위를 대신하지만 결정권자까지 되는 것은 아니라는 권한의 한계를 제시한다."
    },
    {
      "id": "R11",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "이사회가 결정권자가 아니라는 설명을 주요 사항에 관할 기관의 허가가 필요하다는 내용으로 구체화한다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "주요 사항에 허가가 필요하다는 설명을 기본 재산의 처분과 용도 변경이라는 세부 사례로 구체화한다."
    },
    {
      "id": "R13",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "기본 재산과 그 밖의 자산을 운용 방식 및 법적 통제 요건이라는 같은 기준에서 비교한다."
    },
    {
      "id": "R14",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "수익 추구는 허용되지만 영리 목적까지 허용되는 것은 아니며 목적 사업의 재원 마련에 한정된다."
    },
    {
      "id": "R15",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "수익 추구의 허용에 대해 일정 범위 안에서만 가능하다는 한계를 제시한다."
    },
    {
      "id": "R16",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "수익 추구가 허용되더라도 관할 기관에 실적을 보고해야 한다는 통제상의 제한이 따른다."
    },
    {
      "id": "R17",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞에서 제시한 법인격 부여 대상에 따른 분류 기준을 장학 재단이라는 구체적 대상에 적용한다."
    },
    {
      "id": "R18",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "법인에 민법이 적용되지만 영리 목적 법인의 규율이 민법에만 한정되지 않고 상법도 적용됨을 밝힌다."
    },
    {
      "id": "R19",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "구체적인 요건과 절차를 정한 상법도 적용된다는 사실이 통제가 더 정교하다는 평가의 근거가 된다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "주식회사가 사단 법인이라는 사실과 사단 법인의 정의로부터 법인격이 구성원 단체에 부여된다는 판단이 따라 나온다."
    },
    {
      "id": "R21",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "장학 재단과 주식회사가 영리성 및 법인격 부여 대상이라는 같은 기준에서 서로 다른 성격을 보인다."
    },
    {
      "id": "R22",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "재단 법인과 주식회사의 자산 운용 기관이 결정권 보유 여부와 관할 기관의 허가 필요성에서 차이를 보인다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "주식회사 자산의 구성 항목을 제시한 뒤 각 항목의 형성 원천과 기능 및 사용 제한을 자세히 설명한다."
    },
    {
      "id": "R24",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자본금이 지급 능력과 재무 안정성의 기초라는 성격을 근거로 감액 금지 원칙을 설명한다."
    },
    {
      "id": "R25",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "이익 잉여금과 자본 잉여금이 사용 범위와 배당 가능 여부라는 같은 기준에서 차이를 보인다."
    },
    {
      "id": "R26",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "각 자산 항목의 서로 다른 기능과 사용 제한이 항목별 특성에 맞추어 운용한다는 설명을 뒷받침한다."
    },
    {
      "id": "R27",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "자본금 감액 금지라는 원칙에 대해 잉여금으로 손실을 보전할 수 없을 때 자본금을 사용하는 예외를 제시한다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "손실 보전을 위한 자본금 사용이 자본금 감소로 이어져 회사의 존립을 실제로 위태롭게 한다."
    },
    {
      "id": "R29",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자본금 감소가 회사 존립을 위협한다는 사실을 이유로 신중하게 운용해야 한다는 당위를 제시한다."
    },
    {
      "id": "R30",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "외부 유출 여부에 따라 실행 요건이 달라진다는 설명을 무상 증자의 사례로 구체화한다."
    },
    {
      "id": "R31",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "외부 유출 여부에 따른 실행 요건의 차이를 자산 유출을 수반하는 배당의 사례로 보여 준다."
    },
    {
      "id": "R32",
      "type": "CAUSE",
      "otherName": "",
      "reason": "잉여금에 해당하는 주식을 무상 분배하는 행위가 재무 구조가 안정적이라는 인상을 일으킨다."
    },
    {
      "id": "R33",
      "type": "CAUSE",
      "otherName": "",
      "reason": "재무 구조가 안정적이라는 인상이 주가 상승을 유발할 수 있다는 실제 작용을 설명한다."
    },
    {
      "id": "R34",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "무상 증자가 자산 구조의 재편에 그친다는 점을 이사회 결정만으로 실행할 수 있는 근거로 제시한다."
    },
    {
      "id": "R35",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자산의 총 규모가 변하지 않는다는 사실을 근거로 이사회 결정만으로 실행할 수 있음을 설명한다."
    },
    {
      "id": "R36",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "배당이 자산의 외부 유출이라는 사실을 이유로 더 까다로운 요건을 충족해야 한다는 당위를 제시한다."
    },
    {
      "id": "R37",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "무상 증자와 배당이 필요한 의결 기관 및 실행 요건의 엄격성에서 차이를 보인다."
    },
    {
      "id": "R38",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "앞서 뜻을 설명한 배당에 대해 기대 효과와 자산 유출에 따른 실행 요건을 추가로 자세히 설명한다."
    },
    {
      "id": "R39",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "법령 내에서 행사되는 자산 운용 결정권을 무상 증자와 배당의 구체적인 의결 요건으로 풀어 설명한다."
    }
  ]
}

